"""Validate and import embeddings generated by the Colab workflow."""

import argparse
import json
from pathlib import Path
import sys
import time

import numpy as np
from dotenv import load_dotenv
from sqlalchemy import create_engine, select, update
from sqlalchemy.orm import Session

ROOT_DIR = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT_DIR / "backend"))
sys.path.insert(0, str(ROOT_DIR))

from app.db.models import Chunk  # noqa: E402
from scripts.embed.config import EmbeddingConfig  # noqa: E402


def load_and_validate(
    embeddings_path: Path, ids_path: Path, metadata_path: Path, config: EmbeddingConfig
) -> tuple[np.ndarray, np.ndarray, dict[str, object]]:
    embeddings = np.load(embeddings_path, allow_pickle=False)
    ids = np.load(ids_path, allow_pickle=False)
    metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
    if not isinstance(metadata, dict):
        raise ValueError("Metadata must be a JSON object")
    if metadata.get("model") != config.model:
        raise ValueError("Metadata model does not match configured model")
    if metadata.get("dimension") != config.dimension:
        raise ValueError("Metadata dimension does not match configured dimension")
    if embeddings.ndim != 2 or embeddings.shape[1] != config.dimension:
        raise ValueError(
            f"Expected embeddings shape [N, {config.dimension}], got {embeddings.shape}"
        )
    if ids.ndim != 1 or len(ids) != len(embeddings):
        raise ValueError("IDs and embeddings must be one-dimensional and have matching counts")
    if "count" in metadata and metadata["count"] != len(ids):
        raise ValueError("Metadata count does not match embedding count")
    normalized_ids = np.asarray([int(value) for value in ids], dtype=np.int64)
    if len(set(normalized_ids.tolist())) != len(normalized_ids):
        raise ValueError("Duplicate embedding IDs")
    if not np.isfinite(embeddings).all():
        raise ValueError("Embeddings contain non-finite values")
    if np.any(np.linalg.norm(embeddings, axis=1) == 0):
        raise ValueError("Embeddings contain zero-norm vectors")
    return embeddings.astype(np.float32, copy=False), normalized_ids, metadata


def validate_known_ids(ids: np.ndarray, existing_ids: set[int]) -> None:
    unknown = sorted(set(ids.tolist()) - existing_ids)
    if unknown:
        raise ValueError(f"Unknown chunk IDs: {unknown[:10]}")


def import_embeddings(
    embeddings_path: Path,
    ids_path: Path,
    metadata_path: Path,
    *,
    overwrite: bool = False,
    dry_run: bool = False,
    batch_size: int = 500,
) -> dict[str, int]:
    load_dotenv(ROOT_DIR / ".env")
    config = EmbeddingConfig.from_environment()
    embeddings, ids, metadata = load_and_validate(
        embeddings_path, ids_path, metadata_path, config
    )
    database_url = __import__("os").getenv("DATABASE_URL")
    if not database_url:
        raise RuntimeError("DATABASE_URL is not set")
    engine = create_engine(database_url)
    updated = 0
    skipped = 0
    try:
        with Session(engine) as session:
            existing = set(session.scalars(select(Chunk.id).where(Chunk.id.in_(ids.tolist()))))
            validate_known_ids(ids, existing)
            if dry_run:
                if overwrite:
                    updated = len(ids)
                else:
                    updated = sum(
                        1
                        for chunk in session.scalars(
                            select(Chunk).where(Chunk.id.in_(ids.tolist()))
                        )
                        if chunk.embedding is None
                    )
                skipped = len(ids) - updated
            else:
                for start in range(0, len(ids), batch_size):
                    batch_ids = ids[start : start + batch_size]
                    for chunk_id, vector in zip(batch_ids.tolist(), embeddings[start : start + batch_size]):
                        statement = update(Chunk).where(Chunk.id == chunk_id)
                        if not overwrite:
                            statement = statement.where(Chunk.embedding.is_(None))
                        result = session.execute(
                            statement.values(
                                embedding=vector.tolist(),
                                embedding_model=str(metadata["model"]),
                            )
                        )
                        if result.rowcount:
                            updated += result.rowcount
                        else:
                            skipped += 1
                    session.commit()
                    print(f"Processed {min(start + batch_size, len(ids))}/{len(ids)}")
    finally:
        engine.dispose()
    summary = {"input": len(ids), "updated": updated, "skipped": skipped}
    print(("Would update" if dry_run else "Updated") + f" {updated}/{len(ids)} chunks; skipped {skipped}")
    return summary


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--embeddings", type=Path, required=True)
    parser.add_argument("--ids", type=Path, required=True)
    parser.add_argument("--metadata", type=Path, required=True)
    parser.add_argument("--overwrite", action="store_true")
    parser.add_argument("--dry-run", action="store_true")
    parser.add_argument("--batch-size", type=int, default=500)
    args = parser.parse_args(argv)
    if args.batch_size <= 0:
        parser.error("--batch-size must be greater than zero")
    started = time.monotonic()
    import_embeddings(
        args.embeddings,
        args.ids,
        args.metadata,
        overwrite=args.overwrite,
        dry_run=args.dry_run,
        batch_size=args.batch_size,
    )
    print(f"Elapsed seconds: {time.monotonic() - started:.2f}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
